/* TechGlam — storefront demonstrativa, sem backend nem pagamento real.
   Os dados de conta e compras são armazenados somente neste navegador.
   Fotos da análise nunca são enviadas ou persistidas. */
(() => {
'use strict';
const STORAGE='techglam-demo-v1';
const DEFAULT_DB={accounts:{},session:null,guestCart:[],guestFavorites:[],guestAnalysis:null,coupon:'',cep:'',messages:[],newsletter:[]};
let db;
try {db={...DEFAULT_DB,...JSON.parse(localStorage.getItem(STORAGE)||'{}')};} catch {db={...DEFAULT_DB};}
const ui={menu:false,drawer:'',chat:false,chatMessages:[{from:'bot',text:'Oi, eu sou a Lila! 💜 Sua parceira de beleza. Posso te ajudar com produtos, cores, descontos e entregas. Por onde começamos?'}],filters:{category:'Todas',tone:'todos',maxPrice:200,sort:'popular',onSale:false,search:''},filterOpen:false,detailShade:0,detailQty:1,authMode:'login',authReturn:'',accountTab:'overview',orderDone:null,analysis:{stage:'photo',fileName:'',photoUrl:'',photoData:null,consent:false,tone:'médio',undertone:'neutro',question:0,answers:[],processing:false}};
const money=v=>(Number(v)||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const ico=(name,extra='')=>`<svg class="ico ${extra}" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
const img=id=>`./assets/${id}.svg`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{try{localStorage.setItem(STORAGE,JSON.stringify(db));}catch{toast('Não foi possível salvar no navegador.','error');}};
const account=()=>db.session?db.accounts[db.session]||null:null;
const activeCart=()=>account()?account().cart:(db.guestCart??=[]);
const activeFav=()=>account()?account().favorites:(db.guestFavorites??=[]);
const activeAnalysis=()=>account()?.analysis||null||db.guestAnalysis; // replaced below for account isolation
const analysisResult=()=>account()?account().analysis||null:db.guestAnalysis;
const itemById=id=>PRODUCTS.find(p=>p.id===id);
const cartCount=()=>activeCart().reduce((n,it)=>n+it.qty,0);
const toast=(msg,type='success')=>{const node=document.createElement('div');node.className='toast '+(type==='error'?'error':'');node.innerHTML=ico(type==='error'?'close':'check')+`<span>${esc(msg)}</span>`;document.querySelector('#toast-root').append(node);setTimeout(()=>node.remove(),3300);};
const getCampaign=()=>{const d=new Date(),m=d.getMonth()+1,day=d.getDate();if(m===3&&day>=1&&day<=12)return {name:'Mês da Mulher',line:'A beleza de ser exatamente você.',code:'MULHER7',rate:.07};if(m===10)return {name:'Outubro Rosa',line:'Seu brilho começa com o autocuidado.',code:'ROSA7',rate:.07};if(m===11){if(day>=20&&day<=23)return {name:'Consciência Negra',line:'Beleza em todos os tons.',code:'BELEZA7',rate:.07};if(day>=24)return {name:'Black Friday Glam',line:'Favoritos com um toque extra de brilho.',code:'GLAM12',rate:.12};}if(m===12)return {name:'Natal TechGlam',line:'Presentes para iluminar quem você ama.',code:'NATAL7',rate:.07};return {name:'TechGlam Lovers',line:'Seu glow merece um presente.',code:'GLAM5',rate:.05};};
const quantityInCart=(id,shade)=>activeCart().find(it=>it.id===id&&it.shade===shade)?.qty||0;
function addToCart(id,shade=0,qty=1){const p=itemById(id);if(!p){toast('Produto não encontrado.','error');return;}if(p.stock<=0){toast('Produto esgotado no momento.','error');return;}const cart=activeCart(),existing=cart.find(it=>it.id===id&&it.shade===shade);const already=cart.filter(it=>it.id===id).reduce((s,it)=>s+it.qty,0);if(already+qty>p.stock){toast('Quantidade maior que o estoque disponível.','error');return;}if(existing)existing.qty+=qty;else cart.push({id,shade,qty});save();render(false);toast(`${p.name} adicionado ao carrinho!`);}
function changeQty(id,shade,delta){const cart=activeCart(),i=cart.findIndex(it=>it.id===id&&it.shade===shade);if(i<0)return;const p=itemById(id);const inCart=cart.filter(it=>it.id===id).reduce((s,it)=>s+it.qty,0);if(delta>0&&inCart+delta>p.stock){toast('Estoque máximo atingido.','error');return;}cart[i].qty+=delta;if(cart[i].qty<=0)cart.splice(i,1);save();render(false);}
function favorite(id){const list=activeFav(),i=list.indexOf(id);if(i>=0){list.splice(i,1);toast('Removido dos favoritos.');}else{list.push(id);toast('Salvo nos seus favoritos 💜');}save();render(false);}
function shippingPrice(){const cep=(db.cep||'').replace(/\D/g,'');return cep.startsWith('0')||cep.startsWith('1')||cep.startsWith('2')||cep.startsWith('3')?14.9:22.9;}
function totals(){const cart=activeCart();const subtotal=Math.round(cart.reduce((t,it)=>t+(itemById(it.id)?.price||0)*it.qty,0)*100)/100;const coupon=(db.coupon||'').trim().toUpperCase();let couponRate=0,couponLabel='',couponInvalid='';const camp=getCampaign();const user=account();const first=user&&!user.orders?.length;
 if(coupon){if(coupon==='BEMVINDA10'){if(first){couponRate=.10;couponLabel='Primeira compra — 10%';}else couponInvalid='Cupom válido somente na primeira compra de uma conta.';}else if(coupon===camp.code){couponRate=camp.rate;couponLabel=camp.name;}else if(coupon==='GLAM5'){couponRate=.05;couponLabel='Cupom GLAM5';}else couponInvalid='Este cupom não é válido agora.';}
 let lila=0,auto=0,discount=0;if(couponRate){discount=Math.round(subtotal*couponRate*100)/100;}else {const recs=analysisResult()?.recommended||[];lila=Math.round(cart.reduce((t,it)=>t+(recs.includes(it.id)?(itemById(it.id)?.price||0)*it.qty*.08:0),0)*100)/100;auto=subtotal>150?Math.round((subtotal-lila)*.05*100)/100:0;discount=lila+auto;}
 const qualifies=subtotal>150||Boolean(first);const ship=subtotal===0?0:qualifies?0:shippingPrice();return{cart,subtotal,couponRate,couponLabel,couponInvalid,lila,auto,discount,ship,qualifies,first,total:Math.max(0,Math.round((subtotal-discount+ship)*100)/100)};}
function mergeGuestIntoAccount(ac){ac.cart||=[];ac.favorites||=[];ac.orders||=[];for(const it of db.guestCart||[]){const old=ac.cart.find(x=>x.id===it.id&&x.shade===it.shade);const p=itemById(it.id);if(old)old.qty=Math.min(p.stock,old.qty+it.qty);else ac.cart.push({...it});}for(const id of db.guestFavorites||[])if(!ac.favorites.includes(id))ac.favorites.push(id);if(db.guestAnalysis&&!ac.analysis)ac.analysis=db.guestAnalysis;db.guestCart=[];db.guestFavorites=[];db.guestAnalysis=null;}
function navRoute(){return decodeURI((location.hash||'#inicio').slice(1));}
function goto(route){ui.drawer='';ui.menu=false;if(location.hash==='#'+route){render();scrollTo({top:0,behavior:'smooth'});}else location.hash=route;}
function headLink(label,route,clazz=''){return `<a class="${clazz} ${navRoute().split('?')[0]===route?'current':''}" href="#${route}">${label}</a>`;}
function brand(){return `<a href="#inicio" class="brand" aria-label="TechGlam, voltar ao início"><span class="brand-mark">${ico('sparkles')}</span><span class="brand-text">tech<span>glam.</span></span></a>`;}
function header(){return `<div class="announcement">${ico('sparkles')} TECNOLOGIA QUE REALÇA SEU BRILHO <strong>✦</strong> FRETE GRÁTIS ACIMA DE R$ 150</div><header class="header"><div class="container header-main"><button class="icon-action mobile-menu-button" aria-label="Abrir menu" data-action="toggle-menu">${ico('menu')}</button>${brand()}<form class="header-search" id="global-search"><label class="sr-only" for="search-global">Buscar produtos</label><input type="search" id="search-global" name="q" placeholder="O que vai realçar seu brilho hoje?" value="${esc(ui.filters.search)}"/><button type="submit" aria-label="Pesquisar">${ico('search')}</button></form><div class="header-actions"><button class="icon-action" data-action="nav-account" aria-label="Minha conta" title="Minha conta">${ico('user')}</button><button class="icon-action" data-action="go-favs" aria-label="Favoritos" title="Favoritos">${ico('heart')}${activeFav().length?`<span class="bubble">${activeFav().length}</span>`:''}</button><button class="icon-action" data-action="drawer-cart" aria-label="Abrir carrinho" title="Meu carrinho">${ico('bag')}${cartCount()?`<span class="bubble">${cartCount()}</span>`:''}</button></div></div><nav class="nav" aria-label="Menu principal"><div class="container">${headLink('INÍCIO','inicio')}${headLink('TODOS OS PRODUTOS','catalogo')}${headLink('MAQUIAGEM','catalogo?categoria=Paletas%20de%20maquiagem')}${headLink('LÁBIOS','catalogo?categoria=Lip%20oil')}${headLink('OFERTAS','ofertas')}${headLink('LILA GLAM ✦','lila','nav-special')}${headLink('QUEM SOMOS','sobre')}${headLink('CONTATO','contato')}</div></nav><div class="mobile-menu ${ui.menu?'show':''}">${headLink('Início','inicio')}${headLink('Catálogo','catalogo')}${headLink('Ofertas','ofertas')}${headLink('Lila Glam • Análise de coloração','lila')}${headLink('Quem somos','sobre')}${headLink('Contato','contato')}<form id="mobile-search" class="search-form" style="padding:15px 0"><input name="q" style="width:100%" placeholder="Buscar produtos"/></form></div></header>`;}
function footer(){return `<section class="newsletter"><div class="container"><div><span class="eyebrow">NEWSLETTER TECHGLAM</span><h2>Seu glow, na sua caixa de entrada.</h2><p>Receba novidades, dicas e ofertas especiais.</p></div><form id="newsletter-form"><label class="sr-only" for="newsletter-email">Seu e-mail</label><input required id="newsletter-email" type="email" name="email" placeholder="Seu melhor e-mail"/><button class="btn btn-dark" type="submit">Quero receber ${ico('arrow')}</button></form></div></section><footer class="footer"><div class="container"><div class="footer-grid"><div>${brand()}<p class="footer-about">Tecnologia que Realça seu Brilho. Acreditamos na beleza de ser quem você é, com inovação, acolhimento e um toque de magia.</p><div class="footer-social"><a href="https://www.instagram.com/" target="_blank" rel="noopener noreferrer" aria-label="Instagram (exemplo)">ig</a><a href="https://www.tiktok.com/" target="_blank" rel="noopener noreferrer" aria-label="TikTok (exemplo)">tk</a></div></div><div><h4>EXPLORE</h4><a href="#catalogo">Todos os produtos</a><a href="#ofertas">Ofertas</a><a href="#lila">Análise de coloração</a><a href="#favoritos">Meus favoritos</a></div><div><h4>TECHGLAM</h4><a href="#sobre">Nossa história</a><a href="#contato">Fale com a gente</a><a href="#contato">Perguntas frequentes</a><a href="#conta">Minha conta</a></div><div><h4>PRECISA DE AJUDA?</h4><span class="footer-text">Seg–Sex · 9h às 18h</span><span class="footer-text">contato@techglam.exemplo</span><span class="footer-text">(11) 4000-0000</span><span class="footer-text">Contatos demonstrativos</span></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} TechGlam. Protótipo de loja — nenhuma compra ou cobrança é real.</span><span>Feito com 💜 para todos os tons de beleza.</span></div></div></footer>`;}
function sectionHeading(kicker,title,route='catalogo',link='Ver todos'){return `<div class="section-heading"><div><span class="eyebrow">${kicker}</span><h2>${title}</h2></div><a class="view-link" href="#${route}">${link} ${ico('arrow')}</a></div>`;}
function productCard(p){const fav=activeFav().includes(p.id);const label=p.stock===0?'Esgotado':p.tag;const tagClass=p.oldPrice?'sale':p.new?'new':'';return `<article class="product-card"><div class="product-media" data-action="view-product" data-id="${p.id}" role="link" tabindex="0" aria-label="Detalhes de ${esc(p.name)}"><img src="${img(p.id)}" loading="lazy" alt="Ilustração da embalagem de ${esc(p.name)}"/>${label?`<span class="card-label ${tagClass}">${esc(label)}</span>`:''}<button class="heart-btn ${fav?'liked':''}" data-action="favorite" data-id="${p.id}" aria-label="${fav?'Retirar':'Adicionar'} ${esc(p.name)} dos favoritos">${ico('heart')}</button></div><div class="product-content"><span class="product-category">${esc(p.category)}</span><a class="product-name" href="#produto/${p.id}">${esc(p.name)}</a><p class="product-description">${esc(p.desc)}</p><div class="rating"><span class="stars" aria-label="Avaliado em ${p.rating} de 5">★★★★★</span> ${p.rating.toFixed(1).replace('.',',')} (${p.reviews})</div><div class="price-line"><strong class="price">${money(p.price)}</strong>${p.oldPrice?`<span class="old-price">${money(p.oldPrice)}</span>`:''}</div><div class="product-footer"><div class="swatches" title="Tonalidades disponíveis">${p.shades.slice(0,4).map(c=>`<span class="swatch" style="background:${c}"></span>`).join('')}</div><button class="btn btn-primary card-buy" data-action="add-cart" data-id="${p.id}" ${p.stock===0?'disabled':''}>${ico('plus')} ${p.stock===0?'Esgotado':'Adicionar'}</button></div></div></article>`;}
function benefits(){return `<div class="benefits"><div class="container benefits-grid"><div class="benefit">${ico('truck')}<div><strong>Frete grátis acima de R$ 150</strong><p>Mais beleza, menos preocupação</p></div></div><div class="benefit">${ico('gift')}<div><strong>Mimos na primeira compra</strong><p>Use BEMVINDA10*</p></div></div><div class="benefit">${ico('sparkles')}<div><strong>Dicas da Lila Glam</strong><p>Uma experiência feita para você</p></div></div><div class="benefit">${ico('lock')}<div><strong>Compra demonstrativa</strong><p>Explore com total liberdade</p></div></div></div></div>`;}
function home(){const best=[PRODUCTS[0],PRODUCTS[3],PRODUCTS[1],PRODUCTS[2]];const launched=PRODUCTS.filter(p=>p.new&&p.stock>0).slice(0,4);const camp=getCampaign();return `<main><section class="hero"><div class="container"><div class="hero-copy"><div class="eyebrow">✦ BELEZA + INOVAÇÃO + VOCÊ</div><h1>Sua beleza.<br>Seu brilho.<br><em>Suas regras.</em></h1><p>Maquiagem que acompanha o seu jeito de ser. Descubra cores, texturas e uma nova forma de se expressar — com um toque de tecnologia.</p><div class="hero-buttons"><a href="#catalogo" class="btn btn-dark">Explorar coleção ${ico('arrow')}</a><a href="#lila" class="btn btn-outline">Descubra seu glow ${ico('sparkles')}</a></div><div class="hero-points"><span class="flex">${ico('check')} Para todos os tons</span><span class="flex">${ico('check')} Seu match com a Lila</span></div></div><div class="hero-visual"><div class="hero-blob"></div><img class="hero-model" src="./assets/hero-model.svg" alt="Ilustração editorial de uma mulher com maquiagem luminosa"/><span class="hero-circle-word">TECHNOLOGY MEETS BEAUTY ✦</span><div class="float-pill one">${ico('sparkles')}<div><b>Seu match perfeito</b><small>Com ajuda da Lila Glam</small></div></div><div class="float-pill two">${ico('heart')}<div><b>Beleza em cada tom</b><small>Do seu jeito ✨</small></div></div></div></div></section>${benefits()}<section class="section compact"><div class="container">${sectionHeading('EXPLORE SEU UNIVERSO','Escolha seu próximo glow') }<div class="categories">${CATEGORY_FEATURES.map(c=>`<button class="category-tile" data-action="go-category" data-category="${esc(c.category||c.name)}"><span class="category-visual"><img src="${img(c.product)}" alt="" loading="lazy"/></span><strong>${esc(c.name)}</strong><small>${esc(c.subtitle)}</small></button>`).join('')}</div></div></section><section class="section" style="padding-top:20px"><div class="container">${sectionHeading('SEUS FAVORITOS','Os queridinhos da vez')}<div class="product-grid">${best.map(productCard).join('')}</div></div></section><section class="section compact"><div class="container"><div class="lila-banner"><div class="lila-copy"><span class="lila-glow">${ico('sparkles')} CONHEÇA SUA BEAUTY BESTIE</span><h2>Oi, eu sou a <em>Lila Glam.</em> 💜</h2><p>Uma ajudinha extra para descobrir os tons que combinam com você. Faça a experiência de coloração e receba recomendações e benefícios exclusivos!</p><a href="#lila" class="btn btn-cream">Fazer minha análise ${ico('arrow')}</a></div><div class="lila-art"><div class="lila-float">✨ seu glow, sua assinatura!</div><img src="./assets/lila.svg" alt="Lila Glam, mascote virtual da TechGlam" loading="lazy"/></div></div></div></section><section class="section"><div class="container">${sectionHeading('ACABARAM DE CHEGAR','Novidades para amar','catalogo?novos=1','Ver lançamentos')}<div class="product-grid">${launched.map(productCard).join('')}</div></div></section><section class="section compact" style="padding-top:6px"><div class="container"><div class="split-promo"><div class="promo-box"><span class="eyebrow">O GLOW QUE VALE A PENA</span><h3>Seu brilho com preços especiais.</h3><p>Descubra nossos produtos selecionados com desconto.</p><a class="btn btn-dark btn-sm" href="#ofertas">Ver ofertas ${ico('arrow')}</a><img src="${img('glass-glow')}" alt="Lip Oil Glass Glow" loading="lazy"/></div><div class="promo-box violet"><span class="eyebrow">${esc(camp.name.toUpperCase())}</span><h3>${esc(camp.line)}</h3><p>Use <strong>${esc(camp.code)}</strong> para ${Math.round(camp.rate*100)}% OFF*. Benefício não cumulativo.</p><a class="btn btn-outline btn-sm" href="#ofertas">Aproveitar ${ico('arrow')}</a><img src="${img('paleta-aura')}" alt="Paleta de Blush Aura Rosé" loading="lazy"/></div></div><p class="helper" style="margin-top:12px">* Consulte as regras no carrinho. Campanhas e produtos são ilustrativos.</p></div></section><section class="section reviews"><div class="container"><div class="section-heading"><div><span class="eyebrow">COM AMOR, TECHGLAM</span><h2>O brilho vem de dentro.</h2></div></div><div class="review-grid"><div class="review-card"><div class="stars">★★★★★</div><p>“Mais do que maquiagem: um espaço para descobrir o que gosto de verdade.”</p><strong>Beatriz M.</strong><small>Depoimento ilustrativo</small></div><div class="review-card"><div class="stars">★★★★★</div><p>“Os tons, as texturas e a experiência de encontrar um match. Amei a ideia!”</p><strong>Camila R.</strong><small>Depoimento ilustrativo</small></div><div class="review-card"><div class="stars">★★★★★</div><p>“É sobre poder experimentar sem deixar de ser eu mesma.”</p><strong>Júlia A.</strong><small>Depoimento ilustrativo</small></div></div></div></section></main>`;}
function pageHeading(eyebrow,title,desc){return `<section class="page-heading"><div class="container"><div class="breadcrumbs"><a href="#inicio">Início</a><span class="bread-divider">/</span><span>${title.replace(/<[^>]*>/g,'')}</span></div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div></section>`;}
function catalog(isSale=false){const f=ui.filters;let list=PRODUCTS.filter(p=>{
 if(isSale&&!p.oldPrice)return false;
 if(f.category!=='Todas'&&p.category!==f.category)return false;
 if(f.tone!=='todos'&&p.tone!==f.tone)return false;
 if(p.price>f.maxPrice)return false;
 if(f.onSale&&!p.oldPrice)return false;
 if(f.search&&!`${p.name} ${p.category} ${p.desc} ${p.shadeNames.join(' ')}`.toLocaleLowerCase('pt-BR').includes(f.search.toLocaleLowerCase('pt-BR')))return false;return true;});
 const sorting={popular:(a,b)=>b.popularity-a.popularity,priceAsc:(a,b)=>a.price-b.price,priceDesc:(a,b)=>b.price-a.price,new:(a,b)=>Number(b.new)-Number(a.new)||b.popularity-a.popularity,rating:(a,b)=>b.rating-a.rating};list.sort(sorting[f.sort]||sorting.popular);
 return `<main>${pageHeading(isSale?'BELEZA COM BENEFÍCIOS':'UNIVERSO TECHGLAM',isSale?'Ofertas para brilhar':'Tudo para o seu brilho',isSale?'Produtos demonstrativos com preços promocionais.':'Do blush ao gloss, descubra produtos feitos para expressar todas as suas versões.')}<div class="container catalog-layout"><aside class="filter-panel ${ui.filterOpen?'open':''}" aria-label="Filtros de produtos"><div class="between"><h3 style="margin:0">Filtrar por</h3>${ico('filter')}</div><div class="filter-group"><h4>Categoria</h4><label class="check-label"><input type="radio" name="category" data-filter="category" value="Todas" ${f.category==='Todas'?'checked':''}/> Todas as categorias</label>${CATEGORIES.map(cat=>`<label class="check-label"><input type="radio" name="category" data-filter="category" value="${esc(cat)}" ${f.category===cat?'checked':''}/> ${esc(cat)}</label>`).join('')}</div><div class="filter-group"><h4>Tonalidades</h4><select aria-label="Filtrar tonalidades" data-filter="tone"><option value="todos" ${f.tone==='todos'?'selected':''}>Todos os tons</option>${['neutros','rosados','quentes','vibrantes'].map(t=>`<option value="${t}" ${f.tone===t?'selected':''}>${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select></div><div class="filter-group"><h4>Preço máximo</h4><select data-filter="maxPrice" aria-label="Preço máximo">${[50,75,100,150,200].map(v=>`<option value="${v}" ${f.maxPrice===v?'selected':''}>Até ${money(v)}</option>`).join('')}</select></div><div class="filter-group"><label class="check-label"><input type="checkbox" data-filter="onSale" ${f.onSale?'checked':''}/> Somente promoções</label><button class="text-link" data-action="clear-filters">Limpar filtros</button></div></aside><div><div class="catalog-toolbar"><div class="flex"><button class="btn btn-outline btn-sm mobile-filter-toggle" data-action="toggle-filters">${ico('filter')} Filtros</button><p><strong>${list.length}</strong> produtos encontrados${f.search?` para “${esc(f.search)}”`:''}</p></div><label class="flex small" for="sort-products">Ordenar: <select id="sort-products" class="sort-select" data-filter="sort"><option value="popular" ${f.sort==='popular'?'selected':''}>Mais populares</option><option value="new" ${f.sort==='new'?'selected':''}>Lançamentos</option><option value="priceAsc" ${f.sort==='priceAsc'?'selected':''}>Menor preço</option><option value="priceDesc" ${f.sort==='priceDesc'?'selected':''}>Maior preço</option><option value="rating" ${f.sort==='rating'?'selected':''}>Melhores avaliações</option></select></label></div><div class="product-grid">${list.length?list.map(productCard).join(''):`<div class="no-results empty-state"><div class="empty-icon">${ico('search')}</div><h2>Nenhum match por aqui.</h2><p>Tente outros filtros para descobrir seu próximo favorito.</p><button class="btn btn-primary" data-action="clear-filters">Limpar filtros</button></div>`}</div></div></div></main>`;}
function productPage(id){const p=itemById(id);if(!p)return notFound();const s=Math.min(ui.detailShade,p.shades.length-1);return `<main><div class="container"><div class="product-detail"><div class="product-detail-media"><img src="${img(p.id)}" alt="Ilustração da embalagem de ${esc(p.name)}"/>${p.tag?`<span class="card-label ${p.oldPrice?'sale':p.new?'new':''}">${esc(p.tag)}</span>`:''}</div><div class="product-detail-info"><div class="breadcrumbs"><a href="#inicio">Início</a> / <a href="#catalogo">Produtos</a> / ${esc(p.category)}</div><span class="eyebrow">TECHGLAM • ${esc(p.category)}</span><h1>${esc(p.name)}</h1><div class="rating"><span class="stars">★★★★★</span> <strong>${String(p.rating).replace('.',',')}</strong> (${p.reviews} avaliações demonstrativas)</div><p class="lead" style="margin-top:21px">${esc(p.desc)} Uma experiência de maquiagem pensada para destacar a sua beleza, sem abrir mão do conforto, da personalidade e da liberdade de criar.</p><div class="detail-price">${money(p.price)} ${p.oldPrice?`<span class="old-price">${money(p.oldPrice)}</span>`:''}</div><p class="tiny text-muted">Preço de catálogo ilustrativo • Parcelamento simulado</p><div class="detail-option"><h4>Tonalidade: <span id="shade-label">${esc(p.shadeNames[s])}</span></h4><div class="color-picker">${p.shades.map((c,i)=>`<button data-action="choose-shade" data-shade="${i}" class="${s===i?'selected':''}" style="background:${c}" title="${esc(p.shadeNames[i])}" aria-label="Selecionar ${esc(p.shadeNames[i])}" aria-pressed="${s===i}"></button>`).join('')}</div></div><div class="detail-quantity"><div class="qty-ctrl"><button data-action="detail-minus" aria-label="Diminuir quantidade">${ico('minus')}</button><span>${ui.detailQty}</span><button data-action="detail-plus" aria-label="Aumentar quantidade">${ico('plus')}</button></div><span class="product-stock">${p.stock>0?`${p.stock} unidades em estoque (demo)`:'Produto esgotado'}</span></div><div class="flex" style="align-items:stretch;gap:10px"><button class="btn btn-primary" style="flex:1" data-action="add-detail" data-id="${p.id}" ${p.stock===0?'disabled':''}>${ico('bag')} Adicionar ao carrinho</button><button class="btn btn-outline" data-action="favorite" data-id="${p.id}" aria-label="Favoritar produto">${ico('heart')}</button></div><div class="detail-info-card"><div class="detail-info-row">${ico('truck')} Frete grátis em compras acima de R$ 150</div><div class="detail-info-row">${ico('gift')} Cupom BEMVINDA10 na primeira compra</div><div class="detail-info-row">${ico('sparkles')} Desconto Lila para produtos recomendados</div></div></div></div></div><section class="section compact" style="background:#f9f5fa"><div class="container">${sectionHeading('VOCÊ TAMBÉM VAI AMAR','Combine com seu novo favorito')}<div class="product-grid">${PRODUCTS.filter(x=>x.id!==p.id&&x.stock>0).slice(0,4).map(productCard).join('')}</div></div></section></main>`;}
function notFound(){return `<main class="container" style="padding:70px 0">${empty('search','Ops, essa página não existe.','Que tal voltar para descobrir seus novos favoritos?','inicio','Voltar ao início')}</main>`;}
function empty(icon,title,desc,route,label){return `<div class="empty-state"><div class="empty-icon">${ico(icon)}</div><h2>${title}</h2><p>${desc}</p><a class="btn btn-primary" href="#${route}">${label} ${ico('arrow')}</a></div>`;}
function cartLine(it,short=false){const p=itemById(it.id);if(!p)return '';return `<div class="cart-line"><a class="cart-thumb" href="#produto/${p.id}"><img src="${img(p.id)}" alt="${esc(p.name)}"/></a><div><h3><a href="#produto/${p.id}">${esc(p.name)}</a></h3><p>Tom: ${esc(p.shadeNames[it.shade]||p.shadeNames[0])}</p><div class="qty-ctrl"><button data-action="change-qty" data-id="${p.id}" data-shade="${it.shade}" data-delta="-1" aria-label="Diminuir quantidade">${ico('minus')}</button><span>${it.qty}</span><button data-action="change-qty" data-id="${p.id}" data-shade="${it.shade}" data-delta="1" aria-label="Aumentar quantidade">${ico('plus')}</button></div></div><div class="line-end"><strong>${money(p.price*it.qty)}</strong><button data-action="remove-cart" data-id="${p.id}" data-shade="${it.shade}" aria-label="Remover produto" title="Remover">${ico('trash')}</button></div></div>`;}
function progressBlock(t){const left=Math.max(0,150.01-t.subtotal),pct=Math.min(100,t.subtotal/150.01*100);return `<div class="shipping-progress"><p>${t.qualifies?`✨ <strong>Benefício desbloqueado!</strong> Frete grátis ${t.first?'na primeira compra':'por atingir o valor mínimo'}.`:`${ico('truck')} Faltam <strong>${money(left)}</strong> para frete grátis + desconto especial!`}</p><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div></div>`;}
function cartTotals(t,hasCoupon=true){return `<div class="totals"><div class="total-row"><span>Subtotal (${cartCount()} itens)</span><strong>${money(t.subtotal)}</strong></div>${t.lila?`<div class="total-row discount"><span>Desconto Lila Glam (8%)</span><strong>− ${money(t.lila)}</strong></div>`:''}${t.auto?`<div class="total-row discount"><span>Desconto acima de R$ 150 (5%)</span><strong>− ${money(t.auto)}</strong></div>`:''}${t.couponRate?`<div class="total-row discount"><span>${esc(t.couponLabel)}</span><strong>− ${money(t.discount)}</strong></div>`:''}<div class="total-row"><span>Frete estimado</span><strong>${t.ship===0?'Grátis':money(t.ship)}</strong></div><div class="total-row total-final"><span>Total</span><span>${money(t.total)}</span></div>${t.qualifies?'<p class="helper">Frete grátis aplicado automaticamente.</p>':''}${!t.couponRate&&t.lila?'<p class="helper">O desconto Lila é acumulável com o desconto automático por valor. Cupons não acumulam com esses benefícios.</p>':''}</div>`;}
function summaryPanel(t,checkout=false){return `<aside class="panel"><h3>Resumo do pedido</h3>${progressBlock(t)}<div class="divider"></div><h4 class="tiny" style="margin:0 0 10px">Cupom de desconto</h4><form id="coupon-form" class="coupon-form"><label class="sr-only" for="coupon-input">Cupom</label><input id="coupon-input" name="coupon" placeholder="Digite seu cupom" value="${esc(db.coupon)}"/><button type="submit" class="btn btn-outline btn-sm">Aplicar</button></form>${t.couponInvalid?`<p class="inline-error">${esc(t.couponInvalid)}</p>`:''}<p class="helper" style="margin:10px 0">BEMVINDA10 (primeira compra) • ${esc(getCampaign().code)} (campanha atual) • GLAM5. Cupons não cumulativos.</p><div class="divider"></div><h4 class="tiny">Calcule seu frete (simulação)</h4><form id="cep-form" class="cep-form"><label class="sr-only" for="cart-cep">CEP</label><input id="cart-cep" name="cep" inputmode="numeric" maxlength="9" placeholder="00000-000" value="${esc(db.cep)}"/><button class="btn btn-light btn-sm" type="submit">Calcular</button></form>${db.cep?`<p class="helper">Estimativa para CEP ${esc(db.cep)}. Sem integração com transportadora.</p>`:'<p class="helper">O frete é estimado; não há consulta real de endereço.</p>'}<div class="divider"></div>${cartTotals(t)}<div class="spacer"></div>${checkout?'<p class="notice warning">Ambiente demonstrativo: esta etapa não realiza cobrança, pagamento ou envio de produtos.</p>':`<button data-action="checkout" class="btn btn-dark full">Finalizar compra ${ico('arrow')}</button>`}</aside>`;}
function cartPage(){const t=totals();return `<main>${pageHeading('MINHAS ESCOLHAS','Meu carrinho','Confira seus produtos e desbloqueie os benefícios da TechGlam.')}<div class="container">${t.cart.length?`<div class="two-column"><section class="panel"><div class="between"><h2>Seus produtos (${cartCount()})</h2><button class="text-link" data-action="clear-cart">Limpar carrinho</button></div>${t.cart.map(it=>cartLine(it)).join('')}<a class="text-link" href="#catalogo">← Continuar comprando</a></section>${summaryPanel(t)}</div>`:`<div style="padding:44px 0 80px">${empty('bag','Seu carrinho está esperando por você.','Que tal escolher alguns itens para dar aquele up no seu brilho?','catalogo','Explorar produtos')}</div>`}</div></main>`;}
function favoritesPage(){const list=activeFav().map(itemById).filter(Boolean);return `<main>${pageHeading('SEUS DESEJOS','Minha wishlist','Guarde as suas descobertas favoritas para encontrar seu próximo match.')}<div class="container section">${list.length?`<div class="product-grid">${list.map(productCard).join('')}</div><p class="helper" style="margin-top:18px">${account()?'Favoritos vinculados ao perfil demonstrativo.':'Entre na sua conta para associar os favoritos ao seu perfil.'}</p>`:empty('heart','Sua lista ainda está vazia.','Quando algum produto conquistar seu coração, toque no ícone de coração para guardar.','catalogo','Encontrar meus favoritos')}</div></main>`;}
function checkoutPage(){const t=totals();if(!t.cart.length)return `<main>${pageHeading('SEU PEDIDO','Finalização')}<div class="container section">${empty('bag','Seu carrinho está vazio.','Adicione itens para iniciar um pedido demonstrativo.','catalogo','Ver catálogo')}</div></main>`;if(!account()){ui.authReturn='checkout';return loginPage();}return `<main>${pageHeading('QUASE LÁ','Finalizar pedido','Revise seus dados para concluir uma compra simulada, sem qualquer cobrança.')}<div class="container two-column"><section class="panel"><div class="checkout-stages"><span class="active">1 • Entrega</span><span class="active">2 • Pagamento</span><span>3 • Confirmação</span></div><h2>Dados para entrega</h2><form id="checkout-form"><div class="form-grid"><div class="form-field"><label for="check-name">Nome completo</label><input required id="check-name" name="name" value="${esc(account().name)}" minlength="3"/></div><div class="form-field"><label for="check-phone">Telefone</label><input required id="check-phone" name="phone" type="tel" pattern="[0-9() +\-]{10,18}" placeholder="(11) 99999-9999" value="${esc(account().phone||'')}"/></div><div class="form-field"><label for="check-cep">CEP</label><input required id="check-cep" name="cep" pattern="[0-9]{5}-?[0-9]{3}" placeholder="00000-000" value="${esc(db.cep)}"/></div><div class="form-field"><label for="check-number">Número</label><input required id="check-number" name="number" placeholder="Nº" value="${esc(account().address?.number||'')}"/></div></div><div class="form-field"><label for="check-street">Rua / avenida</label><input required id="check-street" name="street" placeholder="Endereço completo" value="${esc(account().address?.street||'')}"/></div><div class="form-grid"><div class="form-field"><label for="check-city">Cidade</label><input required id="check-city" name="city" value="${esc(account().address?.city||'')}"/></div><div class="form-field"><label for="check-state">Estado (UF)</label><input required id="check-state" name="state" maxlength="2" minlength="2" pattern="[A-Za-z]{2}" placeholder="SP" value="${esc(account().address?.state||'')}"/></div></div><div class="divider"></div><h2>Forma de pagamento</h2><div class="form-field"><label for="payment">Escolha um método (simulado)</label><select id="payment" name="payment"><option value="Pix demonstrativo">Pix — demonstração</option><option value="Cartão demonstrativo">Cartão de crédito — demonstração</option><option value="Boleto demonstrativo">Boleto — demonstração</option></select></div><div class="notice warning">${ico('lock')} Nenhum número de cartão, chave Pix ou dado financeiro será solicitado. O botão abaixo gera apenas um pedido fictício.</div><div class="spacer"></div><button class="btn btn-primary full" type="submit">Confirmar pedido simulado • ${money(t.total)} ${ico('arrow')}</button></form></section>${summaryPanel(t,true)}</div></main>`;}
function successPage(){const id=ui.orderDone||db.lastOrderId;return `<main><div class="container order-success"><div class="symbol">${ico('check')}</div><span class="eyebrow">EXPERIÊNCIA FINALIZADA</span><h1>Seu brilho foi confirmado!</h1><p>Pedido <strong>${esc(id||'TG-DEMO')}</strong> criado com sucesso <strong>apenas para demonstração</strong>. Não houve pagamento, envio real ou cobrança. Você pode consultá-lo no histórico da conta.</p><div class="flex" style="justify-content:center;flex-wrap:wrap"><a href="#conta" class="btn btn-primary">Ver meus pedidos ${ico('arrow')}</a><a href="#catalogo" class="btn btn-outline">Voltar à loja</a></div></div></main>`;}
function loginPage(){if(account()&&navRoute()==='login'){return accountPage();}const mode=ui.authMode;return `<main><div class="auth-wrapper"><div class="auth-art"><div class="auth-art-text"><span class="eyebrow light">SEU GLOW COMEÇA AQUI</span><h2>Seu universo de beleza, só seu.</h2></div><img src="./assets/hero-model.svg" alt="Ilustração TechGlam"/></div><div class="auth-content"><span class="eyebrow">BEM-VINDA À TECHGLAM</span><h1>${mode==='register'?'Crie sua conta.':mode==='forgot'?'Sua senha.':'Que bom te ver!'}</h1><p>Salve seus favoritos, conheça seus matches e acompanhe pedidos demonstrativos.</p><div class="auth-switch"><button type="button" class="${mode==='login'?'active':''}" data-action="auth-mode" data-mode="login">Entrar</button><button type="button" class="${mode==='register'?'active':''}" data-action="auth-mode" data-mode="register">Criar conta</button></div><div class="notice warning" style="margin-bottom:21px">Conta demonstrativa salva apenas no seu navegador. Não use uma senha real ou reutilizada; não há servidor ou recuperação por e-mail.</div>${mode==='register'?`<form id="register-form"><div class="form-field"><label for="reg-name">Seu nome</label><input required id="reg-name" name="name" minlength="2" autocomplete="name" placeholder="Como podemos te chamar?"/></div><div class="form-field"><label for="reg-email">E-mail</label><input required id="reg-email" name="email" type="email" autocomplete="email" placeholder="voce@exemplo.com"/></div><div class="form-field"><label for="reg-pass">Senha exclusiva para esta demo</label><input required id="reg-pass" name="password" type="password" minlength="8" autocomplete="new-password" placeholder="No mínimo 8 caracteres"/></div><button type="submit" class="btn btn-primary full">Criar conta demonstrativa ${ico('arrow')}</button></form>`:mode==='forgot'?`<form id="recover-form"><div class="form-field"><label for="recover-email">E-mail cadastrado nesta demonstração</label><input id="recover-email" name="email" type="email" required/></div><div class="form-field"><label for="recover-pass">Nova senha local (mínimo 8 caracteres)</label><input id="recover-pass" name="password" type="password" minlength="8" required/></div><p class="helper">Fluxo exclusivo da demonstração: não há verificação de identidade, e a senha muda somente neste navegador.</p><button class="btn btn-primary full" type="submit">Redefinir nesta demonstração</button></form>`:`<form id="login-form"><div class="form-field"><label for="login-email">E-mail</label><input required id="login-email" name="email" type="email" autocomplete="email" placeholder="seu@email.com"/></div><div class="form-field"><label for="login-pass">Senha</label><input required id="login-pass" name="password" type="password" autocomplete="current-password" placeholder="Sua senha demonstrativa"/></div><div class="between" style="margin-bottom:18px"><span class="helper">Ainda não tem conta? Cadastre-se.</span><button type="button" class="text-link tiny" data-action="auth-mode" data-mode="forgot">Esqueci minha senha</button></div><button class="btn btn-primary full" type="submit">Entrar na minha conta ${ico('arrow')}</button></form>`}</div></div></main>`;}
function accountPage(){const user=account();if(!user){ui.authReturn='conta';return loginPage();}const tab=ui.accountTab;let content='';
 if(tab==='overview'){content=`<span class="eyebrow">BEM-VINDA DE VOLTA</span><h2>Oi, ${esc(user.name.split(' ')[0])}! ✨</h2><p class="text-muted small">Este é seu cantinho TechGlam. Seu brilho merece um espaço especial.</p><div class="values-grid" style="margin:24px 0;grid-template-columns:repeat(3,1fr)"><div class="value-card" style="padding:20px"><strong style="font-size:23px">${(user.orders||[]).length}</strong><p>Pedidos demo</p></div><div class="value-card" style="padding:20px"><strong style="font-size:23px">${user.favorites?.length||0}</strong><p>Favoritos</p></div><div class="value-card" style="padding:20px"><strong style="font-size:23px">${user.analysis?'1':'0'}</strong><p>Análises</p></div></div><div class="notice">${user.analysis?'Sua análise da Lila está salva nesta conta. Os produtos recomendados recebem 8% OFF (exceto quando há cupom aplicado).':'Faça sua análise com a Lila Glam e libere 8% OFF nos produtos recomendados.'}</div><div class="spacer"></div><a class="btn btn-primary" href="#lila">${user.analysis?'Refazer análise':'Conhecer a Lila'} ${ico('sparkles')}</a>`;}
 if(tab==='orders'){content=`<h2>Meus pedidos</h2><p class="text-muted small">Histórico de compras simuladas neste navegador.</p>${user.orders?.length?user.orders.map(o=>`<div class="order-card"><div class="between"><strong>${esc(o.id)}</strong><span class="tag">Pedido simulado</span></div><p>${new Date(o.date).toLocaleDateString('pt-BR')} • ${o.items.length} produtos • ${money(o.total)} • ${esc(o.payment)}</p></div>`).join(''):'<p class="notice">Nenhum pedido ainda. Que tal descobrir a coleção?</p>'}`;}
 if(tab==='profile'){content=`<h2>Meus dados</h2><p class="text-muted small">Dados pessoais salvos somente neste navegador.</p><form id="profile-form"><div class="form-field"><label for="profile-name">Nome</label><input required id="profile-name" name="name" value="${esc(user.name)}"/></div><div class="form-field"><label for="profile-email">E-mail cadastrado</label><input id="profile-email" value="${esc(user.email)}" readonly/></div><div class="form-field"><label for="profile-phone">Telefone</label><input id="profile-phone" name="phone" placeholder="(11) 99999-9999" value="${esc(user.phone||'')}"/></div><div class="form-field"><label for="profile-street">Endereço</label><input id="profile-street" name="street" value="${esc(user.address?.street||'')}"/></div><div class="form-grid"><div class="form-field"><label for="profile-number">Número</label><input id="profile-number" name="number" value="${esc(user.address?.number||'')}"/></div><div class="form-field"><label for="profile-city">Cidade</label><input id="profile-city" name="city" value="${esc(user.address?.city||'')}"/></div></div><div class="form-field"><label for="profile-state">UF</label><input id="profile-state" name="state" maxlength="2" value="${esc(user.address?.state||'')}"/></div><button class="btn btn-primary" type="submit">Salvar alterações</button></form><div class="divider"></div><button class="text-link" data-action="delete-account">Excluir meu cadastro local e meus dados</button><p class="helper">A exclusão apaga este perfil, pedidos, favoritos e histórico da Lila deste navegador.</p>`;}
 if(tab==='coupons'){const camp=getCampaign();content=`<h2>Meus benefícios</h2><p class="text-muted small">Regras configuradas para esta experiência de demonstração.</p><div class="order-card"><strong>BEMVINDA10</strong><p>10% OFF em sua primeira compra com login. Não cumulativo.</p></div><div class="order-card"><strong>${esc(camp.code)}</strong><p>${Math.round(camp.rate*100)}% OFF na campanha ${esc(camp.name)}. Não cumulativo.</p></div><div class="order-card"><strong>GLAM5</strong><p>5% OFF. Não cumulativo.</p></div><div class="order-card"><strong>LILA GLAM • 8%</strong><p>${user.analysis?'Liberado para os seus produtos recomendados.':'Conclua a análise para desbloquear.'} Cumulativo com a promoção automática acima de R$ 150, mas não com cupons.</p></div>`;}
 if(tab==='analysis'){const a=user.analysis;content=`<h2>Minha análise Lila Glam</h2>${a?`<div class="result-banner"><div class="result-color" style="background:${a.skinColor||'#bf9587'}"></div><div><h3>Tom ${esc(a.tone)} • subtom ${esc(a.undertone)}</h3><p>Estimativa experimental feita localmente em ${new Date(a.date).toLocaleDateString('pt-BR')}.</p></div></div><p class="small text-muted" style="margin:20px 0">Produtos sugeridos: ${a.recommended.map(id=>esc(itemById(id)?.name||id)).join(', ')}.</p>`:'<p class="notice">Você ainda não realizou a experiência de coloração.</p>'}<div class="spacer"></div><a href="#lila" class="btn btn-primary">${a?'Refazer':'Começar'} análise ${ico('arrow')}</a>${a?`<div class="spacer"></div><button data-action="delete-analysis" class="text-link">Excluir resultado salvo da Lila</button>`:''}`;}
 const tabs=[['overview','Visão geral','sparkles'],['orders','Pedidos','bag'],['profile','Meus dados','user'],['coupons','Cupons','gift'],['analysis','Lila Glam','heart']];return `<main>${pageHeading('ÁREA PESSOAL','Minha conta','Um espaço pensado para você.')}<div class="container account-grid"><aside class="account-side">${tabs.map(([id,label,icon])=>`<button class="${id===tab?'active':''}" data-action="account-tab" data-tab="${id}">${ico(icon)} ${label}</button>`).join('')}<button data-action="logout">${ico('close')} Sair</button></aside><section class="account-main">${content}</section></div></main>`;}
function lilaPage(){const a=ui.analysis;let body='';if(a.stage==='photo'){body=`<span class="eyebrow">ETAPA 01 • SEU ROSTO, SUA HISTÓRIA</span><h2>Vamos descobrir seus tons?</h2><p>Envie uma fotografia para uma estimativa experimental de luminosidade e subtom. Depois, a gente conhece seus gostos para criar sugestões só suas!</p><div class="notice warning"><strong>Transparência:</strong> esta demonstração faz uma análise simples de pixels no navegador, não usa inteligência artificial nem reconhece rostos. Os resultados podem estar incorretos; você pode ajustar os valores antes de continuar.</div><div class="analysis-guidance"><div class="guidance-item">${ico('check')} Rosto visível, sem maquiagem e sem filtros</div><div class="guidance-item">${ico('check')} Luz natural, sem sombras fortes</div><div class="guidance-item">${ico('check')} Foto centralizada, olhando para frente</div><div class="guidance-item">${ico('check')} JPG, PNG ou WebP • até 6 MB</div></div><label class="consent"><input id="photo-consent" type="checkbox" ${a.consent?'checked':''}/> <span><strong>Concordo com o processamento local da minha foto.</strong> A imagem é mantida somente na memória desta aba para exibição e estimativa, não é enviada, não é salva no armazenamento do navegador e é descartada ao sair/recarregar. Apenas o resultado textual poderá ser salvo.</span></label><div class="upload-area">${ico('camera')}<strong>Escolha sua foto</strong><p>A estimativa funciona melhor com o rosto centralizado e fundo neutro.</p><input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Selecionar foto do rosto" ${a.consent?'':'disabled'}/></div>${a.photoUrl?`<img class="photo-preview" src="${a.photoUrl}" alt="Prévia local da foto selecionada"/><p class="center tiny">${esc(a.fileName)} • processada somente neste navegador</p><div class="form-grid"><div class="form-field"><label for="tone-override">Tom estimado (ajustável)</label><select id="tone-override" data-analysis="tone">${['claro','médio','profundo'].map(t=>`<option value="${t}" ${a.tone===t?'selected':''}>${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select></div><div class="form-field"><label for="undertone-override">Subtom estimado (ajustável)</label><select id="undertone-override" data-analysis="undertone">${['quente','neutro','frio'].map(t=>`<option value="${t}" ${a.undertone===t?'selected':''}>${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select></div></div><p class="helper">A luz e o fundo da imagem afetam significativamente a estimativa.</p>`:''}<div class="analysis-controls"><span class="helper">${a.photoUrl?'✓ Foto carregada':'Aguardando foto e consentimento'}</span><button class="btn btn-primary" data-action="analysis-next" ${a.photoUrl?'':'disabled'}>${a.processing?'Analisando...':'Continuar para o quiz'} ${ico('arrow')}</button></div>`;}
 if(a.stage==='quiz'){const q=QUESTIONS[a.question];body=`<div class="between"><span class="eyebrow">ETAPA 02 • O SEU JEITO DE BRILHAR</span><span class="quiz-counter">${a.question+1} / ${QUESTIONS.length}</span></div><h2 style="margin-top:15px">${esc(q.title)}</h2><p>Não existe resposta certa: a maquiagem deve combinar com você, e não o contrário.</p><div style="margin-top:26px">${q.options.map((opt,i)=>`<button class="quiz-option ${a.answers[a.question]===i?'selected':''}" data-action="quiz-answer" data-option="${i}"><span class="radio-visual"></span>${esc(opt)}</button>`).join('')}</div><div class="analysis-controls"><button class="btn btn-outline" data-action="quiz-back">Voltar</button><button class="btn btn-primary" data-action="quiz-next" ${a.answers[a.question]===undefined?'disabled':''}>${a.question===QUESTIONS.length-1?'Ver meu resultado':'Próxima pergunta'} ${ico('arrow')}</button></div>`;}
 if(a.stage==='result'){const res=analysisResult();if(!res){a.stage='photo';return lilaPage();}const combos=res.tonePref==='quentes'?'pêssego, terracota e cobre':res.tonePref==='vibrantes'?'ameixa, berries e toques de lilás':res.tonePref==='neutros'?'nude, marrom e malva':'rosé, malva e rosa queimado';body=`<span class="eyebrow">ETAPA 03 • MATCH ENCONTRADO</span><h2>Seu brilho é único. ✨</h2><p>Com base na estimativa fotográfica experimental e nas suas preferências, aqui vai uma seleção feita para o seu estilo.</p><div class="result-banner"><div class="result-color" style="background:${esc(res.skinColor)}"></div><div><h3>Tom ${esc(res.tone)} • subtom ${esc(res.undertone)}</h3><p>Estimativa visual não clínica e não definitiva. Iluminação, maquiagem e câmera podem alterar o resultado.</p></div></div><div class="result-list"><strong>Seu mapa de cores:</strong> explore ${esc(combos)}. ${res.finish==='Iluminado / glow'?'Acabamentos luminosos podem destacar os pontos altos do rosto.':res.finish==='Matte aveludado'?'Texturas mais aveludadas podem criar um visual sofisticado.':'Texturas leves ajudam a manter um acabamento equilibrado.'} Teste as cores com calma: você decide o que te faz sentir bem.</div><div class="between" style="margin-top:26px"><h3 style="margin:0">Seus matches TechGlam</h3><span class="tag">${ico('gift')} 8% OFF Lila*</span></div><div class="result-products">${res.recommended.map(id=>{const p=itemById(id);return `<div class="rec-card"><img src="${img(id)}" alt="${esc(p.name)}"/><div class="rec-content"><h4>${esc(p.name)}</h4><p>${esc(recommendReason(p,res))}</p><strong>${money(Math.round(p.price*.92*100)/100)}</strong><p class="helper">Com desconto Lila</p><button class="btn btn-primary btn-sm" data-action="add-cart" data-id="${id}">Adicionar ${ico('plus')}</button></div></div>`;}).join('')}</div><div class="notice success" style="margin-top:21px">${ico('check')} Seu benefício foi desbloqueado: <strong>8% de desconto nos produtos recomendados</strong>, aplicado no carrinho sem cupom. Pode acumular com 5% automático para pedidos acima de R$ 150, mas não com cupons promocionais.</div><p class="helper" style="margin-top:13px">*Benefício válido somente neste protótipo e neste navegador/conta. Nenhum dado fotográfico foi guardado.</p><div class="analysis-controls"><a href="#catalogo" class="btn btn-outline">Ver catálogo</a><button class="btn btn-dark" data-action="reset-analysis">Refazer análise ${ico('arrow')}</button></div>`;}
 const dots=a.stage==='photo'?1:a.stage==='quiz'?2:3;return `<main><section class="analysis-intro"><div class="container"><div><span class="eyebrow">LILA GLAM • EXPERIÊNCIA PERSONALIZADA</span><h1>Descubra seu <em style="color:#976abd">color match.</em></h1><p>Sua beleza tem mil possibilidades. A Lila te ajuda a explorar combinações que fazem sentido para você — com transparência e muito carinho.</p><span class="tag">${ico('sparkles')} Versão demonstrativa • sem IA real</span></div><img src="./assets/lila.svg" alt="Lila Glam, assistente virtual"/></div></section><div class="container"><div class="step-track" aria-label="Progresso da análise: etapa ${dots} de 3"><div class="step-dot done"></div><div class="step-dot ${dots>1?'done':''}"></div><div class="step-dot ${dots>2?'done':''}"></div></div><div class="analysis-box">${body}</div></div></main>`;}
function recommendReason(p,r){const map={'Blush em bastão':'Fórmula prática para modular intensidade e realçar as maçãs do rosto.','Paletas de blush':'Versatilidade para variar tons de blush no mesmo look.','Blush líquido':'Textura leve que combina com sua rotina e acabamento preferido.','Lip oil':'Brilho confortável para completar um visual luminoso.','Lip gloss':'Cor e brilho para destacar os lábios.','Paletas de maquiagem':'Cores para experimentar combinações que combinam com suas preferências.','Pincéis e esponjas':'Ajuda a criar o acabamento do jeito que você gosta.'};return map[p.category]||'Acessório para trazer mais praticidade à sua rotina.';}
function makeRecommendations(a){const answers=a.answers;const tonePref=answers[2]===0?'neutros':answers[2]===1?'rosados':answers[2]===2?'quentes':'vibrantes';const desired=answers[3];const shortlist=tonePref==='quentes'?['coral-crush','sunset-edit','glass-glow','stellar-nude']:tonePref==='vibrantes'?['cherry-aura','lilac-galaxy','berry-glaze','cloud-tint']:tonePref==='neutros'?['stellar-nude','glass-glow','soft-touch','blush-velvet']:['blush-velvet','glass-glow','paleta-aura','cloud-tint'];let special=desired===0?['blush-velvet','cloud-tint']:desired===1?['glass-glow','crystal-kiss']:desired===2?['stellar-nude','lilac-galaxy']:['soft-touch','cloud-puff'];const recs=[...new Set([...special.filter(id=>itemById(id).stock>0).slice(0,1),...shortlist.filter(id=>itemById(id).stock>0),...special.filter(id=>itemById(id).stock>0)])].slice(0,3);return{tone:a.tone,undertone:a.undertone,skinColor:a.photoData?.skinColor||'#bf9587',tonePref,finish:QUESTIONS[4].options[answers[4]],recommended:recs,answers:[...answers],date:new Date().toISOString()};}
function aboutPage(){return `<main><section class="story-hero"><div class="container"><div><span class="eyebrow">NOSSA HISTÓRIA, NOSSO PROPÓSITO</span><h1>Beleza é ser <em style="color:#9466b7">você</em> em todas as suas versões.</h1><p>A TechGlam nasce de uma ideia simples: a tecnologia pode aproximar a beleza das pessoas, nunca impor padrões. Somos uma marca-conceito que combina maquiagem, inovação e personalização para celebrar cada tom, textura e estilo.</p><a href="#catalogo" class="btn btn-dark">Conheça a coleção ${ico('arrow')}</a></div><div class="story-visual"><img src="./assets/hero-model.svg" alt="Arte editorial da TechGlam"/></div></div></section><section class="section"><div class="container"><div class="section-heading"><div><span class="eyebrow">O QUE NOS MOVE</span><h2>Uma nova maneira de se sentir linda.</h2></div></div><div class="values-grid"><div class="value-card">${ico('heart')}<h3>Missão</h3><p>Tornar a maquiagem mais acessível e personalizada, respeitando diferentes tons de pele, identidades e estilos.</p></div><div class="value-card">${ico('sparkles')}<h3>Visão</h3><p>Ser referência em experiências de beleza inclusivas, inteligentes e acolhedoras.</p></div><div class="value-card">${ico('check')}<h3>Valores</h3><p>Diversidade, autoestima, respeito, criatividade, transparência e responsabilidade no uso da tecnologia.</p></div></div></div></section><section class="section compact" style="background:#f4eaf9"><div class="container"><div class="lila-banner"><div class="lila-copy"><span class="eyebrow light">TECNOLOGIA COM PROPÓSITO</span><h2>Personalização sem padrões.</h2><p>A Lila Glam foi idealizada para ajudar cada pessoa a descobrir novas possibilidades de cor. A versão atual é uma experiência demonstrativa: estimativas não substituem avaliações profissionais e não devem definir sua beleza.</p><a class="btn btn-cream" href="#lila">Conheça a Lila ${ico('arrow')}</a></div><div class="lila-art"><img src="./assets/lila.svg" alt="Lila Glam"/></div></div></div></section></main>`;}
function contactPage(){return `<main>${pageHeading('ESTAMOS AQUI POR VOCÊ','Vamos conversar?','Dúvida, sugestão ou vontade de bater um papo sobre maquiagem? Nosso espaço demonstrativo de atendimento está aberto.')}<div class="container contact-grid"><section class="contact-card"><span class="eyebrow">FALE COM A TECHGLAM</span><h2>Conte com a gente.</h2><p class="small text-muted">Preencha o formulário abaixo. Nesta versão, a mensagem é registrada somente no navegador; ela não é enviada a ninguém.</p><form id="contact-form"><div class="form-grid"><div class="form-field"><label for="contact-name">Nome</label><input id="contact-name" name="name" placeholder="Seu nome" minlength="2" required/></div><div class="form-field"><label for="contact-email">E-mail</label><input id="contact-email" name="email" type="email" placeholder="seu@email.com" required/></div></div><div class="form-field"><label for="contact-subject">Assunto</label><select name="subject" id="contact-subject"><option>Dúvida sobre produtos</option><option>Frete e entrega</option><option>Parcerias</option><option>Outros assuntos</option></select></div><div class="form-field"><label for="contact-msg">Sua mensagem</label><textarea id="contact-msg" name="message" placeholder="Escreva aqui..." minlength="10" required></textarea></div><button class="btn btn-primary" type="submit">Registrar mensagem demo ${ico('arrow')}</button></form></section><aside><div class="contact-card"><h2>Fique pertinho.</h2><span class="tag">Dados de contato fictícios</span><div class="info-item">${ico('mail')}<div><h3>E-mail</h3><p>contato@techglam.exemplo</p></div></div><div class="info-item">${ico('user')}<div><h3>Telefone</h3><p>(11) 4000-0000</p></div></div><div class="info-item">${ico('map')}<div><h3>Atendimento demonstrativo</h3><p>Segunda a sexta, das 9h às 18h</p></div></div><button class="btn btn-dark full" data-action="open-chat">${ico('chat')} Conversar com a Lila</button></div><div class="contact-card" style="margin-top:20px"><h2>Dúvidas frequentes</h2>${[['Como funciona a Lila Glam?','A Lila oferece respostas demonstrativas e uma experiência local de cor com questionário. Não há IA conectada nesta versão.'],['Quando tenho frete grátis?','Na primeira compra autenticada ou quando o subtotal de produtos ultrapassa R$ 150,00.'],['Posso comprar sem entrar na conta?','Você pode navegar e adicionar itens. Para concluir um pedido simulado, precisa entrar ou se cadastrar.'],['Como minhas fotos são usadas?','A foto só é processada localmente na aba e não é enviada ou guardada. O resultado textual pode ficar salvo no navegador.'],['Os pagamentos são reais?','Não. Todos os pagamentos e pedidos desta versão são demonstrações.']].map(([q,a])=>`<details class="faq-item"><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></aside></div></main>`;}
function chatWidget(){return `${ui.chat?`<div class="chat-panel" role="dialog" aria-label="Conversa com Lila Glam"><div class="chat-head"><img src="./assets/lila.svg" alt=""/><div><strong>Lila Glam ✨</strong><small>Assistente demonstrativa • respostas guiadas</small></div><button data-action="close-chat" aria-label="Fechar conversa">${ico('close')}</button></div><div class="chat-messages" id="chat-messages">${ui.chatMessages.map(m=>`<div class="chat-message ${m.from==='me'?'mine':''}">${esc(m.text)}</div>`).join('')}</div><div class="chat-chips">${['Frete grátis','Qual blush escolher?','Cupom de desconto','Análise de cores'].map(q=>`<button data-action="chat-chip" data-question="${esc(q)}">${esc(q)}</button>`).join('')}</div><form id="chat-form" class="chat-form"><label class="sr-only" for="chat-input">Mensagem para a Lila</label><input id="chat-input" name="message" autocomplete="off" required placeholder="Pergunte sobre beleza..."/><button type="submit" aria-label="Enviar mensagem">${ico('arrow')}</button></form><div class="chat-footnote">Chat com respostas pré-programadas. Não é IA generativa.</div></div>`:`<button class="chat-fab" data-action="open-chat" aria-label="Abrir chat da Lila Glam"><img src="./assets/lila.svg" alt=""/><span>Fale com a Lila! <small>Seu glow começa aqui ✨</small></span></button>`}`;}
function answerChat(question){const q=question.toLocaleLowerCase('pt-BR');if(/frete|entrega|cep|envio/.test(q))return 'Frete grátis na primeira compra autenticada e em pedidos acima de R$ 150! Fora disso, mostramos um valor estimado após informar seu CEP no carrinho. Nesta demonstração, não realizamos entregas reais.';if(/cupom|desconto|promo|oferta|primeira compra/.test(q))return `Temos BEMVINDA10 na primeira compra, ${getCampaign().code} (${Math.round(getCampaign().rate*100)}%) e GLAM5. 💜 Você também ganha 8% em produtos recomendados depois da análise de cores. Os cupons não acumulam com outros descontos.`;if(/blush|rosa|maquiagem|tom|subtom|pele|recomend/.test(q))return 'Que tal começar com o Blush Stick Velvet Bloom se gosta de rosados ou Coral Crush para um toque mais quente? O ideal é testar pessoalmente. Na análise de coloração você me conta suas preferências e recebe 3 sugestões!';if(/lábio|labio|gloss|oil/.test(q))return 'Para um brilho leve, eu adoro a proposta do Lip Oil Glass Glow. Se quer um acabamento mais evidente, conheça o Crystal Kiss. Você encontra os dois no catálogo! ✨';if(/análise|analise|colora|fotografia|foto|ia|inteligência/.test(q))return 'Na página Lila Glam você envia uma foto com consentimento, recebe uma estimativa visual local, responde 6 perguntas e vê suas sugestões. Importante: esta versão não usa IA real, não reconhece rostos e não envia fotos ao servidor.';if(/pagamento|pix|cartão|cartao|boleto|compra/.test(q))return 'Você pode montar o carrinho sem login e finalizar após entrar. Os métodos Pix, cartão e boleto são simulados: nenhuma cobrança real é realizada.';if(/oi|olá|ola|bom dia|boa tarde|boa noite/.test(q))return 'Oie! 💜 Vamos brilhar? Pergunte sobre blush, lip oil, frete, cupons ou análise de cores.';return 'Amei conversar com você! 💜 Por enquanto, minhas respostas são guiadas e não consigo responder tudo livremente. Posso ajudar com produtos, tons de maquiagem, frete, pagamento, cupons e a análise de coloração. Que tal escolher um desses assuntos?';}
function sendChat(msg){const text=msg.trim().slice(0,500);if(!text)return;ui.chat=true;ui.chatMessages.push({from:'me',text});ui.chatMessages.push({from:'bot',text:answerChat(text)});render(false);const box=document.querySelector('#chat-messages');if(box)box.scrollTop=box.scrollHeight;}
function drawer(){if(ui.drawer!=='cart')return '';const t=totals();return `<div class="drawer-backdrop" data-action="close-drawer"></div><aside class="drawer" role="dialog" aria-label="Seu carrinho" aria-modal="true"><div class="drawer-header"><h2>Minha sacola (${cartCount()})</h2><button class="drawer-close" data-action="close-drawer" aria-label="Fechar">${ico('close')}</button></div>${t.cart.length?`${t.cart.map(it=>cartLine(it,true)).join('')}${progressBlock(t)}<div class="drawer-footer"><div class="between"><span>Subtotal</span><strong>${money(t.subtotal)}</strong></div><div class="spacer"></div><button class="btn btn-dark full" data-action="drawer-to-cart">Ver carrinho e descontos ${ico('arrow')}</button></div>`:`<div class="drawer-empty">${ico('bag')}<h3>Por aqui ainda não tem brilho.</h3><p>Escolha seus favoritos e monte sua sacola.</p><button class="btn btn-primary" data-action="drawer-to-catalog">Explorar catálogo</button></div>`}</aside>`;}
function render(shouldScroll=false){let route=navRoute();if(route.startsWith('produto/'))route='produto';const name=route.split('?')[0];const id=navRoute().split('/')[1];const contents=name==='inicio'||name===''?home():name==='catalogo'?catalog():name==='ofertas'?catalog(true):name==='produto'?productPage(id):name==='carrinho'?cartPage():name==='favoritos'?favoritesPage():name==='checkout'?checkoutPage():name==='login'?loginPage():name==='conta'?accountPage():name==='pedido'?successPage():name==='lila'?lilaPage():name==='sobre'?aboutPage():name==='contato'?contactPage():notFound();document.querySelector('#app').innerHTML=header()+contents+footer()+chatWidget();document.querySelector('#overlay-root').innerHTML=drawer();document.title=(name==='inicio'?'Tecnologia que Realça seu Brilho':({catalogo:'Catálogo',ofertas:'Ofertas',produto:'Produto',carrinho:'Carrinho',favoritos:'Favoritos',checkout:'Finalizar pedido',login:'Entrar',conta:'Minha conta',pedido:'Pedido simulado',lila:'Lila Glam',sobre:'Quem Somos',contato:'Contato'}[name]||'TechGlam'))+' | TechGlam';if(shouldScroll)window.scrollTo({top:0,behavior:'instant'});if(ui.chat){const scroll=document.querySelector('#chat-messages');if(scroll)scroll.scrollTop=scroll.scrollHeight;}document.body.style.overflow=ui.drawer?'hidden':'';}
function parseCatalogRoute(){const raw=navRoute();if(!raw.startsWith('catalogo'))return;const params=new URLSearchParams(raw.split('?')[1]||'');ui.filters.category=CATEGORIES.includes(params.get('categoria'))?params.get('categoria'):'Todas';ui.filters.search=params.get('busca')||'';ui.filters.onSale=params.get('promocoes')==='1';if(params.get('novos')==='1')ui.filters.sort='new';}
function resetAnalysisUI(){if(ui.analysis.photoUrl)URL.revokeObjectURL(ui.analysis.photoUrl);ui.analysis={stage:'photo',fileName:'',photoUrl:'',photoData:null,consent:false,tone:'médio',undertone:'neutro',question:0,answers:[],processing:false};}
function hBytes(buf){return Array.from(new Uint8Array(buf),x=>x.toString(16).padStart(2,'0')).join('');}
function bHex(s){return new Uint8Array(s.match(/.{2}/g).map(b=>parseInt(b,16)));}
async function hashPass(password,salt){if(!globalThis.crypto?.subtle)throw Error('Autenticação demonstrativa requer localhost/HTTPS e um navegador moderno.');const source=new TextEncoder().encode(password);const key=await crypto.subtle.importKey('raw',source,'PBKDF2',false,['deriveBits']);const out=await crypto.subtle.deriveBits({name:'PBKDF2',salt:bHex(salt),iterations:120000,hash:'SHA-256'},key,256);return hBytes(out);}
function newSalt(){return hBytes(crypto.getRandomValues(new Uint8Array(16)));}
function loginSuccess(email){const ac=db.accounts[email];if(!ac)return;mergeGuestIntoAccount(ac);db.session=email;save();toast(`Boas-vindas, ${ac.name.split(' ')[0]}! 💜`);const dest=ui.authReturn||'conta';ui.authReturn='';goto(dest);}
async function analyzeFile(file){if(!ui.analysis.consent){toast('Marque o consentimento antes de escolher a foto.','error');return;}if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Formato inválido. Use JPG, PNG ou WebP.','error');return;}if(file.size>6*1024*1024){toast('A foto deve ter no máximo 6 MB.','error');return;}const a=ui.analysis;if(a.photoUrl)URL.revokeObjectURL(a.photoUrl);a.photoUrl=URL.createObjectURL(file);a.fileName=file.name.slice(0,60);a.processing=true;render(false);try{const result=await estimateSkinColor(a.photoUrl);a.photoData=result;a.tone=result.tone;a.undertone=result.undertone;toast('Estimativa cromática local concluída. Você pode ajustar o resultado.');}catch(e){console.error(e);a.photoData={skinColor:'#bf9587'};a.tone='médio';a.undertone='neutro';toast('Não foi possível analisar os pixels. Ajuste as opções manualmente.','error');}finally{a.processing=false;render(false);}}
function estimateSkinColor(url){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{try{const canvas=document.createElement('canvas');const w=160,h=160;canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(im,0,0,w,h);const {data}=ctx.getImageData(0,0,w,h);const colors=[];for(let y=47;y<111;y+=3){for(let x=52;x<108;x+=3){const i=(y*w+x)*4,r=data[i],g=data[i+1],b=data[i+2],alpha=data[i+3];const max=Math.max(r,g,b),min=Math.min(r,g,b),light=(r+g+b)/3;if(alpha<220||light<55||light>239||max-min>105)continue;colors.push([r,g,b]);}}
 if(colors.length<18)throw new Error('A imagem não tem pixels de referência suficientes.');const median=ch=>{const s=colors.map(c=>c[ch]).sort((a,b)=>a-b);return s[Math.floor(s.length/2)]};const [r,g,b]=[median(0),median(1),median(2)];const lum=.2126*r+.7152*g+.0722*b;const tone=lum>170?'claro':lum>120?'médio':'profundo';const undertone=r-g>17&&g-b>5?'quente':b>r-3?'frio':'neutro';resolve({skinColor:`rgb(${r}, ${g}, ${b})`,tone,undertone});}catch(e){reject(e);}};im.onerror=()=>reject(new Error('Imagem inválida'));im.src=url;});}
async function handleSubmit(e){const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const values=Object.fromEntries(new FormData(form).entries());
 if(form.id==='global-search'||form.id==='mobile-search'){ui.filters.search=String(values.q||'').trim();ui.filters.category='Todas';ui.filters.sort='popular';goto('catalogo?busca='+encodeURIComponent(ui.filters.search));return;}
 if(form.id==='newsletter-form'){const email=String(values.email||'').trim().toLowerCase();if(!db.newsletter.includes(email))db.newsletter.push(email);save();form.reset();toast('E-mail salvo nesta demonstração. Nenhum newsletter será enviado.');return;}
 if(form.id==='coupon-form'){db.coupon=String(values.coupon||'').trim().toUpperCase();save();const t=totals();render(false);toast(t.couponInvalid?t.couponInvalid:db.coupon?'Cupom aplicado ao carrinho.':'Cupom removido.',t.couponInvalid?'error':'success');return;}
 if(form.id==='cep-form'){const cep=String(values.cep||'').replace(/\D/g,'');if(!/^\d{8}$/.test(cep)){toast('Digite um CEP com 8 números.','error');return;}db.cep=cep.slice(0,5)+'-'+cep.slice(5);save();render(false);toast('Estimativa de frete recalculada.');return;}
 if(form.id==='chat-form'){sendChat(values.message||'');return;}
 if(form.id==='register-form'){try{const name=String(values.name||'').trim();const email=String(values.email||'').trim().toLowerCase();const pass=String(values.password||'');if(name.length<2||pass.length<8){toast('Confira nome e senha (mínimo 8 caracteres).','error');return;}if(db.accounts[email]){toast('Este e-mail já possui cadastro demonstrativo.','error');return;}const salt=newSalt();const passHash=await hashPass(pass,salt);db.accounts[email]={email,name,salt,passHash,cart:[],favorites:[],orders:[],analysis:null,address:{}};loginSuccess(email);}catch(err){toast(err.message,'error');}return;}
 if(form.id==='login-form'){const email=String(values.email||'').trim().toLowerCase();const p=db.accounts[email];if(!p){toast('Conta não encontrada nesta demonstração. Crie uma conta primeiro.','error');return;}try{if(await hashPass(String(values.password||''),p.salt)!==p.passHash){toast('Senha incorreta.','error');return;}loginSuccess(email);}catch(err){toast(err.message,'error');}return;}
 if(form.id==='recover-form'){const email=String(values.email||'').trim().toLowerCase(),p=db.accounts[email];if(!p){toast('Não encontramos esse cadastro local.','error');return;}try{const salt=newSalt();p.salt=salt;p.passHash=await hashPass(String(values.password||''),salt);save();ui.authMode='login';render(false);toast('Senha local alterada (demo, sem verificação de identidade).');}catch(err){toast(err.message,'error');}return;}
 if(form.id==='profile-form'){const ac=account();if(!ac)return;ac.name=String(values.name||'').trim();ac.phone=String(values.phone||'').trim();ac.address={...ac.address,street:String(values.street||''),number:String(values.number||''),city:String(values.city||''),state:String(values.state||'').toUpperCase()};save();render(false);toast('Dados de demonstração atualizados.');return;}
 if(form.id==='checkout-form'){if(!account()){ui.authReturn='checkout';goto('login');return;}const zipcode=String(values.cep||'').replace(/\D/g,'');if(!/^\d{8}$/.test(zipcode)){toast('CEP inválido.','error');return;}db.cep=zipcode.slice(0,5)+'-'+zipcode.slice(5);const t=totals();if(!t.cart.length){goto('catalogo');return;}const ac=account();ac.name=String(values.name||'').trim();ac.phone=String(values.phone||'').trim();ac.address={cep:db.cep,street:String(values.street||''),number:String(values.number||''),city:String(values.city||''),state:String(values.state||'').toUpperCase()};const id='TG-'+new Date().getFullYear()+'-'+String(Date.now()).slice(-7);(ac.orders??=[]).unshift({id,date:new Date().toISOString(),items:t.cart.map(x=>({...x,name:itemById(x.id)?.name})),subtotal:t.subtotal,discount:t.discount,shipping:t.ship,total:t.total,payment:String(values.payment)});ac.cart=[];db.coupon='';db.lastOrderId=id;ui.orderDone=id;save();toast('Pedido de demonstração registrado!');goto('pedido');return;}
 if(form.id==='contact-form'){db.messages.push({name:String(values.name||'').trim(),email:String(values.email||'').trim(),subject:String(values.subject||''),message:String(values.message||'').trim(),date:new Date().toISOString()});save();form.reset();toast('Mensagem registrada no navegador. Não houve envio real.');return;}
}
function handleClick(e){const target=e.target.closest('[data-action]');if(!target)return;const act=target.dataset.action,id=target.dataset.id,shade=Number(target.dataset.shade||0);if(act==='view-product'||act==='go-category'){if(act==='go-category')goto('catalogo?categoria='+encodeURIComponent(target.dataset.category));else{ui.detailQty=1;ui.detailShade=0;goto('produto/'+id);}return;}
 if(act==='toggle-menu'){ui.menu=!ui.menu;render(false);return;}if(act==='nav-account'){ui.authReturn='conta';goto(account()?'conta':'login');return;}if(act==='go-favs'){goto('favoritos');return;}
 if(act==='drawer-cart'){ui.drawer='cart';render(false);return;}if(act==='close-drawer'){ui.drawer='';render(false);return;}if(act==='drawer-to-cart'){ui.drawer='';goto('carrinho');return;}if(act==='drawer-to-catalog'){ui.drawer='';goto('catalogo');return;}
 if(act==='add-cart'){addToCart(id,0,1);return;}if(act==='favorite'){favorite(id);return;}if(act==='change-qty'){changeQty(id,shade,Number(target.dataset.delta));return;}if(act==='remove-cart'){const cart=activeCart(),i=cart.findIndex(it=>it.id===id&&it.shade===shade);if(i>=0){cart.splice(i,1);save();render(false);toast('Produto removido do carrinho.');}return;}
 if(act==='clear-cart'){activeCart().splice(0);save();render(false);toast('Carrinho esvaziado.');return;}if(act==='checkout'){if(!account()){ui.authReturn='checkout';ui.authMode='login';toast('Faça login ou cadastre-se para finalizar. Seu carrinho será preservado.');goto('login');}else goto('checkout');return;}
 if(act==='clear-filters'){ui.filters={category:'Todas',tone:'todos',maxPrice:200,sort:'popular',onSale:false,search:''};goto('catalogo');render(false);return;}if(act==='toggle-filters'){ui.filterOpen=!ui.filterOpen;render(false);return;}
 if(act==='choose-shade'){ui.detailShade=shade;render(false);return;}if(act==='detail-plus'){const p=itemById(navRoute().split('/')[1]);ui.detailQty=Math.min(p?.stock||1,ui.detailQty+1);render(false);return;}if(act==='detail-minus'){ui.detailQty=Math.max(1,ui.detailQty-1);render(false);return;}if(act==='add-detail'){addToCart(id,ui.detailShade,ui.detailQty);return;}
 if(act==='auth-mode'){ui.authMode=target.dataset.mode;render(false);return;}if(act==='logout'){db.session=null;ui.authReturn='';db.coupon='';save();goto('inicio');toast('Você saiu da sua conta de demonstração.');return;}if(act==='account-tab'){ui.accountTab=target.dataset.tab;render(false);return;}
 if(act==='open-chat'){ui.chat=true;render(false);const field=document.querySelector('#chat-input');if(field)field.focus();return;}if(act==='close-chat'){ui.chat=false;render(false);return;}if(act==='chat-chip'){sendChat(target.dataset.question);return;}
 if(act==='analysis-next'){if(!ui.analysis.photoUrl||!ui.analysis.consent){toast('Selecione uma foto e confirme o consentimento.','error');return;}ui.analysis.stage='quiz';ui.analysis.question=0;render(false);return;}
 if(act==='quiz-answer'){ui.analysis.answers[ui.analysis.question]=Number(target.dataset.option);render(false);return;}
 if(act==='quiz-back'){if(ui.analysis.question>0)ui.analysis.question--;else ui.analysis.stage='photo';render(false);return;}
 if(act==='quiz-next'){const a=ui.analysis;if(a.answers[a.question]===undefined){toast('Escolha uma alternativa para continuar.','error');return;}if(a.question<QUESTIONS.length-1){a.question++;render(false);}else{const result=makeRecommendations(a);if(account())account().analysis=result;else db.guestAnalysis=result;save();a.stage='result';if(a.photoUrl){URL.revokeObjectURL(a.photoUrl);a.photoUrl='';}render(false);toast('Seu desconto da Lila já está liberado!');}return;}
 if(act==='reset-analysis'){resetAnalysisUI();render(false);return;}
 if(act==='delete-analysis'){if(account()){account().analysis=null;save();render(false);toast('Resultado da Lila excluído deste navegador.');}return;}
 if(act==='delete-account'){if(account()&&window.confirm('Excluir permanentemente este cadastro local, seus favoritos e pedidos demonstrativos?')){delete db.accounts[db.session];db.session=null;db.coupon='';save();goto('inicio');toast('Cadastro local excluído.');}return;}
}
function handleChange(e){const t=e.target;if(t.dataset.filter){const k=t.dataset.filter;if(k==='onSale')ui.filters[k]=t.checked;else if(k==='maxPrice')ui.filters[k]=Number(t.value);else ui.filters[k]=t.value;render(false);return;}if(t.id==='photo-consent'){ui.analysis.consent=t.checked;if(!t.checked&&ui.analysis.photoUrl){resetAnalysisUI();}render(false);return;}if(t.id==='photo-input'&&t.files?.[0]){analyzeFile(t.files[0]);return;}if(t.dataset.analysis){ui.analysis[t.dataset.analysis]=t.value;return;}}
window.addEventListener('hashchange',()=>{parseCatalogRoute();ui.menu=false;ui.drawer='';render(true);});
document.addEventListener('submit',e=>{handleSubmit(e).catch(err=>{console.error(err);toast('Não foi possível concluir a operação.','error');});});
document.addEventListener('click',handleClick);
document.addEventListener('change',handleChange);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(ui.drawer){ui.drawer='';render(false);}else if(ui.chat){ui.chat=false;render(false);}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-action="view-product"]')){e.preventDefault();e.target.click();}});
window.addEventListener('beforeunload',()=>{if(ui.analysis.photoUrl)URL.revokeObjectURL(ui.analysis.photoUrl);});
parseCatalogRoute();render(false);
})();
